// --- Payload validation ---
// Validate that the incoming payload contains the required keys.
const body = $input.first().json;
const required = ['incident_id', 'user_id', 'telemetry', 'assessment'];
const missing = required.filter(k => !(k in body));
if (missing.length) {
  throw new Error('Missing required keys: ' + missing.join(', '));
}

const t = body.telemetry;
const telemetryFields = ['email','role','account_type','last_active_days','accessed_resources','failed_login_attempts','location_anomaly','privilege_level'];
const tm = telemetryFields.filter(k => !(k in t));
if (tm.length) {
  throw new Error('Telemetry missing: ' + tm.join(', '));
}

return [{
  json: {
    ...body,
    validation: { ok: true, validated_at: new Date().toISOString() }
  }
}];

// --- Data preparation ---
// Build the prompt payload Gemini expects.
const item = $input.first().json;
const t = item.telemetry;
const a = item.assessment || {};

const prompt = `Assess the following security telemetry for a single user account. Return ONLY the JSON object defined by the schema — no commentary, no markdown fences.

Email: ${t.email}
Role: ${t.role}
Account type: ${t.account_type}
Privilege level: ${t.privilege_level}
Days since last activity: ${t.last_active_days}
Failed login attempts: ${t.failed_login_attempts}
Location anomaly detected: ${t.location_anomaly}
Accessed resources: ${(t.accessed_resources || []).join(', ') || 'none'}

Score 0-100 with justification and a recommended action.`;

return [{
  json: {
    ...item,
    gemini_request: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0.1,
        maxOutputTokens: 1024,
        responseMimeType: 'application/json'
      }
    }
  }
}];

// --- Gemini response parsing ---
// Extract the candidate text and parse as JSON.
const item = $input.first().json;
const candidates = item.candidates || [];
if (!candidates.length) throw new Error('Gemini returned no candidates');
const text = candidates[0].content?.parts?.[0]?.text || '';
if (!text) throw new Error('Gemini returned empty text');

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Gemini response is not valid JSON: ' + text.slice(0, 200));
}

return [{
  json: {
    ...item,
    gemini_assessment: parsed
  }
}];

// --- Threat score validation ---
const item = $input.first().json;
const a = item.gemini_assessment || {};
const errors = [];

if (typeof a.threat_score !== 'number' || a.threat_score < 0 || a.threat_score > 100) {
  errors.push('threat_score out of range');
}
if (!['LOW','MEDIUM','HIGH','CRITICAL'].includes(a.risk_category)) {
  errors.push('invalid risk_category');
}
if (!['MONITOR','FLAG','REQUIRE_REVOCATION_APPROVAL','REVOKE_IMMEDIATELY'].includes(a.recommended_action)) {
  errors.push('invalid recommended_action');
}
if (typeof a.reasoning !== 'string' || a.reasoning.length < 10) {
  errors.push('reasoning missing/too short');
}

return [{
  json: {
    ...item,
    validation: {
      ...item.validation,
      gemini_valid: errors.length === 0,
      errors: errors
    }
  }
}];

// --- Risk classification ---
const item = $input.first().json;
const a = item.gemini_assessment || item.assessment || {};
const score = a.threat_score || 0;
let category;
if (score >= 75) category = 'CRITICAL';
else if (score >= 50) category = 'HIGH';
else if (score >= 25) category = 'MEDIUM';
else category = 'LOW';

return [{
  json: {
    ...item,
    classification: { score, category, recommended_action: a.recommended_action || 'MONITOR' }
  }
}];

// HIGH/CRITICAL branch — request human approval in live mode.
// In simulation mode, mock revocation proceeds automatically.
const item = $input.first().json;
return [{
  json: {
    ...item,
    iam_action: {
      mode: item.assessment?.simulation_mode ? 'SIMULATION' : 'LIVE',
      action: item.assessment?.simulation_mode ? 'REVOKED' : 'PENDING_APPROVAL',
      timestamp: new Date().toISOString()
    }
  }
}];

// Mock IAM revocation — simulates disabling the account.
const item = $input.first().json;
return [{
  json: {
    ...item,
    iam_result: {
      previous_status: 'ACTIVE',
      new_status: 'REVOKED',
      revoked_at: new Date().toISOString(),
      incident_id: item.incident_id,
      approver: item.assessment?.simulation_mode ? 'simulation-engine' : null
    }
  }
}];

// LOW/MEDIUM branch — flag the account for monitoring.
const item = $input.first().json;
return [{
  json: {
    ...item,
    iam_action: {
      action: item.classification.category === 'MEDIUM' ? 'FLAGGED' : 'MONITORED',
      timestamp: new Date().toISOString()
    }
  }
}];

// --- Error handling ---
// Capture any prior node failure and report it cleanly.
const item = $input.first().json;
return [{
  json: {
    incident_id: item.incident_id,
    user_id: item.user_id,
    error: item.error || 'Pipeline failed',
    timestamp: new Date().toISOString()
  }
}];

